@startuml

class SensorController {
  + systemName : string
  + querySensorValues(inhabitantID : string) : void
  + checkThresholds() : void
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
  + email : string
  + isAdmin : boolean
}

class Room {
  + description : string
}

class Sensor {
  + vendorID : string
  + description : string
  + unit : Unit
  + threshold : float
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + totalConsumption : float
}

class SensorValue {
  + timestamp : datetime
  + value : float
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + checkThresholds() : void
  + sendAlert(email : string) : void
}

SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Inhabitant "1..*" -- "1" Apartment
Inhabitant "1" -- "0..*" Sensor : configures
Room "1" -- "1..*" Sensor
Sensor "1" *-- "1..*" SensorValue
Sensor "1" -- "0..1" SensorValue : lastValue
SensorController "1" -- "0..*" Sensor
EMonitor "1" ..> SensorController : attached
EMonitor "1" ..> Sensor : checksThresholds
Inhabitant "1" -- "0..*" Sensor : queries

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

